// Direct native22 coupled action of mapped first/second/mixed derivatives.
#include "goal1_typed_support.hpp"
#include "goal1_physical_native.hpp"
#include "goal1_operator_oracle.hpp"
#include <chrono>
#include <iomanip>
#include <iostream>
namespace cs=cubed_sphere;namespace h=z4c::hyperboloidal;
using State=h::Z4cJet<Real>;
State InitialDeviation(const Real x[3],Real amplitude,Real width){
 cs::Jet y[3];Real z=0;for(int d=0;d<3;++d){y[d]=cs::Jet(x[d]);y[d].d[d]=1;z+=x[d]*x[d];}Real w2=width*width,f=exp(-z/w2),b=1-z;cs::Jet pulse(pow(b,4)*f);Real fp=f*(-4*pow(b,3)-pow(b,4)/w2),fpp=f*(12*b*b+8*pow(b,3)/w2+pow(b,4)/(w2*w2));for(int d=0;d<3;++d){pulse.d[d]=2*x[d]*fp;for(int e=0;e<3;++e)pulse.h[d][e]=4*x[d]*x[e]*fpp+(d==e?2*fp:0);}
 cs::Jet values[4]={amplitude*pulse*(cs::Jet(1)+.2*y[0]+.3*y[1]*y[2]),amplitude/2*pulse*(cs::Jet(1)+.3*y[1]*y[2]),amplitude*.1*pulse*y[0],amplitude*.05*pulse*y[0]*y[1]};State u{};for(int n=0;n<4;++n){h::ScalarJet<Real>s{};s.value=values[n].f;for(int d=0;d<3;++d){s.d[d]=values[n].d[d];for(int e=0;e<3;++e)s.dd[d][e]=values[n].h[d][e];}cs::research_interface::StoreScalar(u,18+n,s);}return u;
}
int main(int argc,char**argv){Kokkos::initialize(argc,argv);std::cout<<std::setprecision(17);int status=0;try{
 const int na=16,nr=24;const Real amplitude=.001,width=.35;auto start=std::chrono::steady_clock::now();cs::research_interface::Physical op(na,nr,cs::Map{.25,.98,0});const int N=op.W.size();h::LayerReference<Real>reference(1.,.5,{true,.05,.95});std::vector<State>discrete(N);
 std::array<std::vector<Real>,4>data;for(int n=0;n<4;++n){data[n].resize(N);for(int i=0;i<N;++i)data[n][i]=cs::operator_oracle::Component(InitialDeviation(op.points[i].x,amplitude,width),18+n).value;}
 struct Stats{int cells=0;Real mass=0,rhs=0,rhsmax=0,first=0,firstmax=0,second=0,secondmax=0,mixed=0,comm=0,commmax=0;};std::array<Stats,7>stats{};std::array<Real,22>component2{},componentmax{};Real raw_stationary=0,dettime=0,Atime=0,Hmax=0,Mmax=0,Zmax=0;std::vector<Real>gradient_error(N),second_error(N),mixed_error(N),comm_error(N);
 for(int n=0;n<4;++n){std::array<std::vector<Real>,3>df;std::array<std::vector<Real>,9>dd;for(int d=0;d<3;++d)df[d]=op.D[d].Apply(data[n]);for(int d=0;d<3;++d)for(int e=0;e<3;++e)dd[3*d+e]=op.D[d].Apply(df[e]);for(int i=0;i<N;++i){auto exact=cs::operator_oracle::Component(InitialDeviation(op.points[i].x,amplitude,width),18+n);h::ScalarJet<Real>s{};s.value=data[n][i];for(int d=0;d<3;++d){s.d[d]=df[d][i];gradient_error[i]+=pow((s.d[d]-exact.d[d])/(amplitude/width),2);for(int e=0;e<3;++e){s.dd[d][e]=.5*(dd[3*d+e][i]+dd[3*e+d][i]);Real error=(s.dd[d][e]-exact.dd[d][e])/(amplitude/(width*width));second_error[i]+=error*error;if(d!=e){mixed_error[i]+=error*error;comm_error[i]+=pow((dd[3*d+e][i]-dd[3*e+d][i])/(amplitude/(width*width)),2);}}}cs::research_interface::StoreScalar(discrete[i],18+n,s);}}
 for(int i=0;i<N;++i){const auto&point=op.points[i];auto ref=reference.At(point.x[0],point.x[1],point.x[2]);auto exact=InitialDeviation(point.x,amplitude,width);h::AddBackgroundJet(exact,ref.state);h::AddBackgroundJet(discrete[i],ref.state);auto connection=rwm::ReferenceConnection(ref,point.x);auto analytic=cs::typed_support::Core(exact,ref,connection);auto rhs=cs::typed_support::Core(discrete[i],ref,connection);auto stationary=cs::typed_support::Core(ref.state,ref,connection);Real error2=0;for(int n=0;n<22;++n){Real scale=(n==0||(n>=1&&n<=6)||n>=18)?amplitude/width:amplitude/(width*width);Real error=(rhs[n]-analytic[n])/scale;error2+=error*error;component2[n]+=op.W[i]*error*error;componentmax[n]=std::max(componentmax[n],std::abs(error));raw_stationary=std::max(raw_stationary,std::abs(stationary[n]));}
  auto geometry=h::Geometry(discrete[i].metric);Real tr=0,ta=0;const int a[6]={0,0,0,1,1,2},b[6]={0,1,2,1,2,2};Real fm[3][3]{},fa[3][3]{};for(int n=0;n<6;++n){fm[a[n]][b[n]]=fm[b[n]][a[n]]=rhs[1+n];fa[a[n]][b[n]]=fa[b[n]][a[n]]=rhs[8+n];}for(int a=0;a<3;++a)for(int b=0;b<3;++b){tr+=geometry.inverse[a][b]*fm[a][b];ta+=geometry.inverse[a][b]*fa[a][b];for(int c=0;c<3;++c)for(int d=0;d<3;++d)ta-=geometry.inverse[a][c]*fm[c][d]*geometry.inverse[d][b]*discrete[i].a.k[a][b];}dettime=std::max(dettime,std::abs(geometry.determinant*tr));Atime=std::max(Atime,std::abs(ta));auto constraints=h::EvolvedConstraints(discrete[i],h::CartesianOmega(discrete[i],ref));Hmax=std::max(Hmax,std::abs(constraints.hamiltonian));Mmax=std::max(Mmax,std::sqrt(constraints.momentum_physical_norm2));Zmax=std::max(Zmax,std::sqrt(constraints.z4.z_conformal_norm2));
  int block=0;while(block<6&&i>=op.blocks[block+1].start)++block;const auto&bl=op.blocks[block];int local=i-bl.start,ix=local%bl.n[0],iy=(local/bl.n[0])%bl.n[1],iz=local/(bl.n[0]*bl.n[1]);int seam=(iy<4||iy>=bl.n[1]-4)+(iz<4||iz>=bl.n[2]-4);bool masks[7]={true,block==0,block!=0,block!=0&&ix<4,block!=0&&seam==1,block!=0&&seam==2,block!=0&&ref.radius>.9};for(int r=0;r<7;++r)if(masks[r]){auto&s=stats[r];++s.cells;s.mass+=op.W[i];s.rhs+=op.W[i]*error2;s.rhsmax=std::max(s.rhsmax,std::sqrt(error2));s.first+=op.W[i]*gradient_error[i];s.firstmax=std::max(s.firstmax,std::sqrt(gradient_error[i]));s.second+=op.W[i]*second_error[i];s.secondmax=std::max(s.secondmax,std::sqrt(second_error[i]));s.mixed+=op.W[i]*mixed_error[i];s.comm+=op.W[i]*comm_error[i];s.commmax=std::max(s.commmax,std::sqrt(comm_error[i]));}}
 std::cout<<"{\"native_evolved_field_components\":22,\"additional_evolved_fields\":0,\"nodes\":"<<N<<",\"seconds\":"<<std::chrono::duration<Real>(std::chrono::steady_clock::now()-start).count()<<",\"raw_stationary_rhs_max\":"<<raw_stationary<<",\"native_det_time_max\":"<<dettime<<",\"native_A_trace_time_max\":"<<Atime<<",\"initial_H_max\":"<<Hmax<<",\"initial_M_physical_max\":"<<Mmax<<",\"initial_Z_conformal_max\":"<<Zmax<<",\"regions\":[";const char*names[7]={"all","bulk","shell","cube-shell","seam-edge","seam-corner","outer-collar"};for(int r=0;r<7;++r){if(r)std::cout<<",";auto&s=stats[r];std::cout<<"{\"region\":\""<<names[r]<<"\",\"cells\":"<<s.cells<<",\"mass\":"<<s.mass<<",\"native_rhs_normalized_rms\":"<<sqrt(s.rhs/s.mass)<<",\"native_rhs_normalized_linf\":"<<s.rhsmax<<",\"first_normalized_rms\":"<<sqrt(s.first/s.mass)<<",\"first_normalized_linf\":"<<s.firstmax<<",\"second_normalized_rms\":"<<sqrt(s.second/s.mass)<<",\"second_normalized_linf\":"<<s.secondmax<<",\"mixed_normalized_rms\":"<<sqrt(s.mixed/s.mass)<<",\"commutator_normalized_rms\":"<<sqrt(s.comm/s.mass)<<",\"commutator_normalized_linf\":"<<s.commmax<<"}";}std::cout<<"],\"components\":[";for(int n=0;n<22;++n)std::cout<<(n?",":"")<<"{\"native_field\":"<<n<<",\"rhs_normalized_rms\":"<<sqrt(component2[n]/stats[0].mass)<<",\"rhs_normalized_linf\":"<<componentmax[n]<<"}";std::cout<<"],\"evolution_trajectories\":0,\"complete_boundary_method_admitted\":false}"<<std::endl;
 }catch(const std::exception&e){std::cerr<<e.what()<<std::endl;status=2;}Kokkos::finalize();return status;}
